<template><div class="page"><div class="page-head"><div><h2>风险规则</h2><p>使用可配置规则代替大量硬编码 if，新增指标时自动匹配规则。</p></div><el-button type="primary" v-if="auth.has('rule:write')" @click="open()">新增规则</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="ruleName" label="规则名称" min-width="180"/><el-table-column prop="riskType" label="风险类型"/><el-table-column prop="metricCode" label="指标编码"/><el-table-column prop="operatorCode" label="运算符" width="90"/><el-table-column prop="thresholdValue" label="阈值"/><el-table-column prop="riskLevel" label="等级" width="90"><template #default="s"><el-tag :type="tag(s.row.riskLevel)">{{s.row.riskLevel}}</el-tag></template></el-table-column><el-table-column prop="enabled" label="启用" width="80"><template #default="s">{{s.row.enabled?'是':'否'}}</template></el-table-column><el-table-column prop="description" label="说明" min-width="180"/><el-table-column label="操作" width="140" v-if="auth.has('rule:write')"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="form.id?'编辑规则':'新增规则'" width="580px"><el-form label-width="90px"><el-form-item label="规则名称"><el-input v-model="form.ruleName"/></el-form-item><el-form-item label="风险类型"><el-input v-model="form.riskType"/></el-form-item><el-form-item label="指标编码"><el-input v-model="form.metricCode"/></el-form-item><el-row :gutter="12"><el-col :span="12"><el-form-item label="运算符"><el-select v-model="form.operatorCode" style="width:100%"><el-option label="> 大于" value="GT"/><el-option label=">= 大于等于" value="GE"/><el-option label="< 小于" value="LT"/><el-option label="<= 小于等于" value="LE"/><el-option label="环比增长超过%" value="CHANGE_GT"/><el-option label="环比下降超过%" value="CHANGE_LT"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="阈值"><el-input-number v-model="form.thresholdValue" :precision="4" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="风险等级"><el-select v-model="form.riskLevel" style="width:100%"><el-option label="高 HIGH" value="HIGH"/><el-option label="中 MEDIUM" value="MEDIUM"/><el-option label="低 LOW" value="LOW"/></el-select></el-form-item><el-form-item label="说明"><el-input type="textarea" v-model="form.description"/></el-form-item><el-form-item label="启用"><el-switch v-model="enabledBool"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{ref,computed,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{api}from'../api';import{useAuthStore}from'../stores/auth';const auth=useAuthStore();const rows=ref([]),loading=ref(false),visible=ref(false);const blank=()=>({ruleName:'',riskType:'经营异常',metricCode:'CHURN_RATE',operatorCode:'GT',thresholdValue:0.2,riskLevel:'HIGH',enabled:1,description:''});const form=ref(blank());const enabledBool=computed({get:()=>form.value.enabled===1,set:v=>form.value.enabled=v?1:0});function tag(l){return l==='HIGH'?'danger':l==='MEDIUM'?'warning':'success'}async function load(){loading.value=true;try{rows.value=(await api.rules())||[]}finally{loading.value=false}}function open(r){form.value=r?{...r}:blank();visible.value=true}async function save(){form.value.id?await api.updateRule(form.value.id,form.value):await api.createRule(form.value);ElMessage.success('保存成功');visible.value=false;load()}async function remove(id){await ElMessageBox.confirm('确定删除规则？','提示',{type:'warning'});await api.deleteRule(id);load()}onMounted(load)</script>
